"""Local analytics: statistics generated by this application, from your own projects.

There is no platform API import here. Every number comes from the app's own database,
and the API response says so explicitly so a user never mistakes it for YouTube or
Instagram performance data.
"""
from __future__ import annotations

from datetime import timedelta

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.models import AgentTask, Clip, Project, Thumbnail, Video
from app.models.base import utcnow
from app.services.storage import disk_usage_mb

SOURCE_NOTE = ("These are locally generated application statistics from your own projects. "
               "No platform analytics have been imported.")


def overview(db: Session, user_id: str) -> dict:
    def count(model, *where) -> int:
        return int(db.scalar(select(func.count()).select_from(model).where(*where)) or 0)

    video_seconds = float(db.scalar(
        select(func.coalesce(func.sum(Video.duration_s), 0.0)).where(Video.user_id == user_id)) or 0.0)
    clip_rows = db.scalars(select(Clip).where(Clip.user_id == user_id)).all()
    clip_seconds = sum(c.duration_s for c in clip_rows)

    return {
        "projects": count(Project, Project.user_id == user_id),
        "videos": count(Video, Video.user_id == user_id),
        "videos_processed": count(Video, Video.user_id == user_id, Video.status == "ready"),
        "clips": len(clip_rows),
        "clips_ready": sum(1 for c in clip_rows if c.status == "ready"),
        "thumbnails": count(Thumbnail, Thumbnail.user_id == user_id),
        "total_video_seconds": round(video_seconds, 1),
        "total_clip_seconds": round(clip_seconds, 1),
        "tasks_succeeded": count(AgentTask, AgentTask.user_id == user_id, AgentTask.status == "succeeded"),
        "tasks_failed": count(AgentTask, AgentTask.user_id == user_id, AgentTask.status == "failed"),
        "storage_mb": disk_usage_mb(),
        # Stated by the service so the API, the agent and the UI all say the same thing.
        "source_note": SOURCE_NOTE,
    }


def detail(db: Session, user_id: str) -> dict:
    data = overview(db, user_id)

    # Activity: clips created per day for the last 7 days.
    since = utcnow() - timedelta(days=6)
    rows = db.execute(
        select(func.date(Clip.created_at), func.count(Clip.id))
        .where(Clip.user_id == user_id, Clip.created_at >= since)
        .group_by(func.date(Clip.created_at))
    ).all()
    by_day = {str(day): int(n) for day, n in rows}
    activity = []
    for i in range(6, -1, -1):
        day = (utcnow() - timedelta(days=i)).date()
        activity.append({"label": day.strftime("%a"), "value": by_day.get(str(day), 0)})

    platform_rows = db.execute(
        select(Clip.platform, func.count(Clip.id)).where(Clip.user_id == user_id)
        .group_by(Clip.platform)
    ).all()
    by_platform = [{"label": p or "unknown", "value": int(n)} for p, n in platform_rows]

    recent_rows = db.scalars(
        select(Clip).where(Clip.user_id == user_id).order_by(Clip.created_at.desc()).limit(8)
    ).all()
    recent = [{
        "id": c.id, "title": c.title, "platform": c.platform, "status": c.status,
        "duration_s": c.duration_s, "score": c.score,
        "created_at": c.created_at.isoformat(),
    } for c in recent_rows]

    data.update({"activity": activity, "by_platform": by_platform, "recent": recent})
    return data
